func VersionLT(v uint32) queryscope.Scope  { return queryscope.Less("version", v) }
func VersionLTE(v uint32) queryscope.Scope { return queryscope.LessEqual("version", v) }
func VersionIn(values ...uint32) queryscope.Scope {
	args := make([]any, len(values))
	for i, v := range values {
		args[i] = v
	}
	return queryscope.In("version", args...)
}
func VersionNotIn(values ...uint32) queryscope.Scope {
	args := make([]any, len(values))
	for i, v := range values {
		args[i] = v
	}
	return queryscope.NotIn("version", args...)
}
func VersionIsNil() queryscope.Scope  { return queryscope.IsNull("version") }
func VersionNotNil() queryscope.Scope { return queryscope.NotNull("version") }
func ByVersion(descending ...bool) queryscope.Scope {
	return queryscope.OrderBy("version", len(descending) > 0 && descending[0])
}
func And(predicates ...queryscope.Scope) queryscope.Scope { return queryscope.And(predicates...) }
func Or(predicates ...queryscope.Scope) queryscope.Scope  { return queryscope.Or(predicates...) }
func Not(predicate queryscope.Scope) queryscope.Scope     { return queryscope.Not(predicate) }
